abstract class Employee{String name,id;Employee(String n,String i){name=n;id=i;}abstract double monthlySalary();}class FullTime extends Employee{FullTime(String n,String i){super(n,i);}double monthlySalary(){return 40000;}}class PartTime extends Employee{int hours;double rate;PartTime(String n,String i,int h,double r){super(n,i);hours=h;rate=r;}double monthlySalary(){return hours*rate;}}class Intern extends Employee{Intern(String n,String i){super(n,i);}double monthlySalary(){return 10000;}}public class PayrollDemo{public static void main(String[]x){Employee[] a={new FullTime("A","1"),new PartTime("B","2",40,200),new Intern("C","3")};double total=0;for(Employee e:a){System.out.println(e.name+": "+e.monthlySalary()+(e instanceof Intern?" (Intern)":""));total+=e.monthlySalary();}System.out.println("Total="+total);}}
